// Resized WebP copies live next to originals: <cdn>/images/<name>.<ext> -> <cdn>/<prefix>/<name>.webp
// Generated by scripts/generate-thumbs.mjs (backfill) and lib/upload.js (new uploads). Keep the sizes in sync with the script.
export const IMAGE_VARIANTS = [
  { name: 'thumb', prefix: 'thumbs', width: 480, quality: 72 }, // grids and cards
  { name: 'medium', prefix: 'medium', width: 800, quality: 78 }, // main product image (original only while zooming)
  { name: 'tiny', prefix: 'tiny', width: 160, quality: 70 }, // gallery strip
];

const ORIGINAL = /^(https:\/\/cdn\.[^/]+)\/images\/([^/?#]+)\.(?:png|jpe?g|webp|gif)$/i;

export function variantUrl(url, variant = 'thumb') {
  if (!url || typeof url !== 'string' || variant === 'original') return url;
  const v = IMAGE_VARIANTS.find((x) => x.name === variant);
  const m = v && url.match(ORIGINAL);
  return m ? `${m[1]}/${v.prefix}/${m[2]}.webp` : url;
}
